def g(rows, cols, cells):
    out = [[0] * cols for _ in range(rows)]
    for r, c in cells:
        out[r][c] = 1
    return out

around = [(1, 1), (1, 2), (1, 3), (2, 1), (2, 3), (3, 1), (3, 2), (3, 3)]
for alive in (0, 1):
    for n in range(9):
        cells = around[:n] + ([(2, 2)] if alive else [])
        got = step(g(5, 5, cells))[2][2]
        want = 1 if n == 3 or (alive and n == 2) else 0
        assert got == want, f'a {"live" if alive else "dead"} cell with {n} live neighbours should become {want}; got {got}'

